ak & van Gennep uitgever Singel Uitgeverijen taal Nederlands","sha256":"cb19ba8f29b4e844fdfa9d5673c3ac80c0d8cc9ffb3f3de3ca53a78eddb0d67c","checkedAt":"2026-11-01T13:59:39.915Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Jane Austen"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/24846/trots-en-vooroordeel.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-02-20261101","review_status":"approved","bound_author_id":977300001},"before_row":null},{"key":{"id":977200103},"seq":21,"relation":"editions","after_row":{"id":977200103,"title":"Spaar de spotvogel","isbn_10":null,"isbn_13":"9789023494935","work_id":977100019,"cover_id":null,"language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200103},"seq":22,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100019,"evidence":[{"url":"https://metadata.isbn.nl/192922/spaar-de-spotvogel.html","fact":"Paperback ISBN 9789023494935 verschijningsdatum 06/05/2015 NUR 302 Vertaalde literaire roman, novelle imprint De bezige bij Amsterdam uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sha256":"531c47c6fb28a3d24ce37a2848338be73f64e321dfe7d0bead556affedf90157","checkedAt":"2026-11-01T13:59:42.112Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Harper Lee"},{"url":"https://metadata.isbn.nl/ie_fcache/0000056610_Spaar_de_spotvogel_0_0.jpg","fact":"Exact ISBN block image + human visual title/author review, sheet2","bytes":80075,"sha256":"9a9449217b8e71bda09a800b939299fa4401d84af91d1344f8ef48d41083e3e6","checkedAt":"2026-11-01T14:19:42.231Z"}],"cover_url":